193: function createCar(x, z) {
194:   const root = new THREE.Group(); root.position.set(x, 0, z); world.add(root);
195:   const body = mat(0x171a22, .26, .62), glass = mat(0x42516a, .18, .42);
196:   box(root, [2.5, .75, 4.3], [0, .72, 0], body);
197:   box(root, [2.05, .85, 2.1], [0, 1.42, -.14], body);
198:   box(root, [1.87, .62, .06], [0, 1.48, .95], glass);
199:   box(root, [1.87, .6, .06], [0, 1.48, -1.18], glass);
200:   box(root, [.08, .68, 1.82], [-1.02, 1.48, -.12], glass); box(root, [.08, .68, 1.82], [1.02, 1.48, -.12], glass);
201:   for (const side of [-1, 1]) for (const zz of [-1.42, 1.43]) {
202:     const wheel = cylinder(root, .48, .48, .22, [side * 1.2, .43, zz], mat(0x0b0c11, .38, .2), 14); wheel.rotation.z = Math.PI / 2;
203:     cylinder(root, .25, .25, .24, [side * 1.2, .43, zz], M.gold, 12).rotation.z = Math.PI / 2;
204:   }
205:   for (const side of [-1, 1]) {
206:     box(root, [.45, .22, .05], [side * .78, .84, -2.17], mat(0xc9484b, .4, 0, 0x9f151a, .8));
207:     box(root, [.42, .2, .05], [side * .78, .89, 2.17], mat(0xffdf9a, .4, 0, 0xf0bc62, .9));
208:   }
209:   return root;
210: }
211: function buildRain(count) {
212:   const positions = new Float32Array(count * 3), velocities = new Float32Array(count);
213:   for (let i = 0; i < count; i++) {
214:     positions[i * 3] = (Math.random() - .5) * 38; positions[i * 3 + 1] = Math.random() * 17; positions[i * 3 + 2] = (Math.random() - .5) * 42;
215:     velocities[i] = 7 + Math.random() * 8;
216:   }
217:   const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
218:   const material = new THREE.PointsMaterial({ color: 0xa6c6ef, size: .035, transparent: true, opacity: .48, depthWrite: false });
219:   rain = new THREE.Points(geo, material); rainPositions = positions; rainVelocities = velocities; world.add(rain);
220: }
