const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({
    channel: 'chromium',
    headless: true,
    args: ['--enable-gpu','--ignore-gpu-blocklist','--enable-unsafe-webgpu','--use-angle=vulkan','--enable-features=Vulkan','--use-vulkan=swiftshader','--use-webgpu-adapter=swiftshader','--disable-vulkan-surface']
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
  page.on('console', msg => console.log('BROWSER', msg.type(), msg.text()));
  page.on('pageerror', err => console.log('PAGEERR', err.message));
  await page.goto('http://localhost:8000', { waitUntil: 'load', timeout: 30000 });
  // start game
  await page.click('#start-btn');
  await page.waitForTimeout(5000);
  console.log('after start objective', await page.locator('#objective-text').innerText());
  console.log('dialogue', await page.locator('#dialogue').evaluate(el => el.classList.contains('hidden') ? 'hidden' : 'shown'));
  // if still in intro, wait a bit.
  await page.waitForTimeout(1500);
  console.log('after more wait objective', await page.locator('#objective-text').innerText());
  // Try to move forward in theater
  await page.keyboard.down('KeyW');
  await page.waitForTimeout(1500);
  await page.keyboard.up('KeyW');
  console.log('after move objective', await page.locator('#objective-text').innerText());
  // Interact
  await page.keyboard.press('KeyE');
  await page.waitForTimeout(1000);
  console.log('after interact objective', await page.locator('#objective-text').innerText());
  console.log('ending visible?', await page.locator('#ending').evaluate(el => el.classList.contains('hidden')));
  console.log('state', await page.evaluate(() => document.body.innerText.slice(0,2000)));
  await browser.close();
})();
