262:   const forward = (keys.KeyW || keys.ArrowUp || move.up ? 1 : 0) - (keys.KeyS || keys.ArrowDown || move.down ? 1 : 0);
263:   const sideways = (keys.KeyD || keys.ArrowRight || move.right ? 1 : 0) - (keys.KeyA || keys.ArrowLeft || move.left ? 1 : 0);
264:   // The theater lobby lies ahead at +Z; the avenue/car route runs toward -Z.
265:   const vector = new THREE.Vector3(sideways, 0, stage === 'theater' ? forward : -forward);
266:   if (vector.lengthSq()) {
267:     vector.normalize().applyAxisAngle(new THREE.Vector3(0, 1, 0), camAngle);
268:     const speed = 3.65 * dt;
269:     player.position.x = THREE.MathUtils.clamp(player.position.x + vector.x * speed, -7.3, 7.3);
270:     player.position.z = THREE.MathUtils.clamp(player.position.z + vector.z * speed, stage === 'theater' ? -13.6 : -12.5, stage === 'theater' ? 13 : 10.5);
271:     // Actor models face their local -Z axis.
272:     player.rotation.y = Math.atan2(-vector.x, -vector.z);
273:   }
274:   if (stage === 'theater' && parents.length) {
275:     // Thomas and Martha walk ahead toward the lobby, always keeping Bruce in sight.
276:     for (const [index, actor] of parents.entries()) {
277:       const target = new THREE.Vector3((index === 0 ? -.75 : .75), 0, 12.25 - index * .35);
278:       actor.position.lerp(target, Math.min(1, dt * .34));
279:       actor.rotation.y = Math.PI;
280:     }
281:   }
282:   if (stage === 'city' && parents.length) {
283:     // The family stays together on the sidewalk as Bruce heads for the car.
284:     for (const [index, actor] of parents.entries()) {
285:       const side = index === 0 ? -1.05 : -2.0;
286:       const target = new THREE.Vector3(player.position.x + side, 0, player.position.z + 1.15 + index * .45);
287:       actor.position.lerp(target, Math.min(1, dt * 2.4));
288:       actor.position.x = THREE.MathUtils.clamp(actor.position.x, -6.5, 6.5);
289:       actor.rotation.y = player.rotation.y;
290:     }
291:     if (player.position.distanceTo(car.position) < 2.8) showPrompt('GET IN THE CAR');
